// Builds the side-by-side review page (an HTML artifact for the user's marks) from the
// committed markdown page. Deterministic. Usage: node scripts/limelight-side-by-side-html.mjs [out.html]
// The markdown source is generated by scripts/limelight-side-by-side.mjs; regenerate it first.
import { readFileSync, writeFileSync } from 'node:fs';

const SRC = new URL('../docs/design/2026-09-02-limelight-side-by-side.md', import.meta.url).pathname;
const OUT = process.argv[2] ?? new URL('../dist-side-by-side.html', import.meta.url).pathname;

const md = readFileSync(SRC, 'utf8').split('\n');
const sections = [];
let cur = null;
for (const line of md) {
  const h = /^## (.+?) \((\d+)\)\s*$/.exec(line);
  if (h) { cur = { title: h[1], count: Number(h[2]), rows: [] }; sections.push(cur); continue; }
  if (!cur) continue;
  const m = /^\| `([^`]+)` \| (.*?) \| (.*?) \| (.*?) \|\s*(.*?)\s*\|\s*$/.exec(line);
  if (m) cur.rows.push({ key: m[1], def: m[2], lime: m[3], board: m[4] });
}
const total = sections.reduce((n, s) => n + s.rows.length, 0);
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

const nav = sections.map((s) => `<a href="#${slug(s.title)}">${esc(s.title)} <span class="n">${s.rows.length}</span></a>`).join('');
const tables = sections.map((s) => `
<section id="${slug(s.title)}" class="screen">
  <h2>${esc(s.title)} <span class="n">${s.rows.length}</span></h2>
  <div class="tablewrap">
  <table>
    <thead><tr><th scope="col">Key</th><th scope="col">Clinical (default)</th><th scope="col">Limelight</th><th scope="col">Board</th><th scope="col">Your mark</th></tr></thead>
    <tbody>
${s.rows.map((r) => `      <tr data-key="${esc(r.key)}" data-search="${esc((r.key + ' ' + r.def + ' ' + r.lime + ' ' + r.board).toLowerCase())}">
        <th scope="row"><code>${esc(r.key)}</code></th>
        <td class="def">${esc(r.def)}</td>
        <td class="lime">${esc(r.lime)}</td>
        <td class="board${r.board === 'same' ? ' same' : ''}">${esc(r.board)}</td>
        <td class="mark"><input type="text" inputmode="text" autocomplete="off" spellcheck="false" placeholder="keep / cut / your string" aria-label="Your mark for ${esc(r.key)}" data-key="${esc(r.key)}"></td>
      </tr>`).join('\n')}
    </tbody>
  </table>
  </div>
</section>`).join('\n');

const html = `<title>Limelight Side-by-Side</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,400..900&family=JetBrains+Mono:wght@400;600&display=swap">
<style>
:root{
  --bg:#0b0b0a; --bg-2:#141412; --line:#2a2a26; --line-2:#3a3a34;
  --text:#f2f2ec; --text-2:#b8b8ae; --text-3:#8a8a80;
  --lime:#8ace00; --lime-ink:#0b0b0a; --lime-dim:rgba(138,206,0,.14);
  --board:#ffb000; --board-dim:rgba(255,176,0,.10);
  --mark:#ff5fcb; --mark-dim:rgba(255,95,203,.12);
  --mono:'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  --sans:'Archivo',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  color-scheme:dark;
}
@media (prefers-color-scheme: light){
  :root:not([data-theme="dark"]){
    --bg:#f6f6f1; --bg-2:#ffffff; --line:#dcdcd2; --line-2:#c6c6ba;
    --text:#141412; --text-2:#4a4a44; --text-3:#7a7a70;
    --lime:#5d8c00; --lime-ink:#ffffff; --lime-dim:rgba(93,140,0,.12);
    --board:#9a6500; --board-dim:rgba(154,101,0,.10);
    --mark:#b5188a; --mark-dim:rgba(181,24,138,.10);
    color-scheme:light;
  }
}
:root[data-theme="light"]{
  --bg:#f6f6f1; --bg-2:#ffffff; --line:#dcdcd2; --line-2:#c6c6ba;
  --text:#141412; --text-2:#4a4a44; --text-3:#7a7a70;
  --lime:#5d8c00; --lime-ink:#ffffff; --lime-dim:rgba(93,140,0,.12);
  --board:#9a6500; --board-dim:rgba(154,101,0,.10);
  --mark:#b5188a; --mark-dim:rgba(181,24,138,.10);
  color-scheme:light;
}
:root[data-theme="dark"]{
  --bg:#0b0b0a; --bg-2:#141412; --line:#2a2a26; --line-2:#3a3a34;
  --text:#f2f2ec; --text-2:#b8b8ae; --text-3:#8a8a80;
  --lime:#8ace00; --lime-ink:#0b0b0a; --lime-dim:rgba(138,206,0,.14);
  --board:#ffb000; --board-dim:rgba(255,176,0,.10);
  --mark:#ff5fcb; --mark-dim:rgba(255,95,203,.12);
  color-scheme:dark;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);font-size:15px;line-height:1.45}
a{color:inherit}
header{padding:28px 20px 12px;border-bottom:1px solid var(--line);background:var(--bg)}
.eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--lime)}
h1{font-family:var(--sans);font-variation-settings:'wdth' 75;font-weight:850;font-size:clamp(28px,6vw,44px);line-height:1;margin:6px 0 10px;text-wrap:balance;text-transform:lowercase}
h1 .m{color:var(--lime)}
.lede{max-width:62ch;color:var(--text-2);margin:0 0 6px}
.lede b{color:var(--text)}
.rules{max-width:62ch;margin:14px 0 0;padding:12px 14px;border:1px solid var(--line);border-radius:4px;background:var(--bg-2);color:var(--text-2)}
.rules p{margin:0 0 8px}
.rules p:last-child{margin:0}
.marks{display:flex;gap:10px;flex-wrap:wrap;margin:10px 0 0;font-family:var(--mono);font-size:12px}
.marks span{padding:3px 8px;border:1px solid var(--line-2);border-radius:3px}
.marks span b{color:var(--mark)}
.tools{position:sticky;top:0;z-index:5;display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:10px 20px;background:var(--bg);border-bottom:1px solid var(--line)}
.tools input[type=search]{flex:1 1 220px;min-height:40px;padding:8px 12px;border:1px solid var(--line-2);border-radius:4px;background:var(--bg-2);color:var(--text);font:inherit}
.tools input[type=search]:focus-visible{outline:2px solid var(--lime);outline-offset:1px}
.tools .count{font-family:var(--mono);font-size:12px;color:var(--text-3);min-width:9ch}
.tools button{min-height:40px;padding:8px 14px;border:1px solid var(--lime);border-radius:4px;background:var(--lime);color:var(--lime-ink);font:inherit;font-weight:700;cursor:pointer}
.tools button.quiet{background:transparent;color:var(--text);border-color:var(--line-2)}
.tools button:focus-visible{outline:2px solid var(--mark);outline-offset:2px}
nav.jump{display:flex;gap:6px;flex-wrap:wrap;padding:10px 20px;border-bottom:1px solid var(--line)}
nav.jump a{font-family:var(--mono);font-size:12px;text-decoration:none;padding:5px 9px;border:1px solid var(--line);border-radius:3px;color:var(--text-2)}
nav.jump a:hover,nav.jump a:focus-visible{border-color:var(--lime);color:var(--text);outline:none}
.n{color:var(--text-3);font-weight:400;font-family:var(--mono);font-size:.8em}
main{padding:0 20px 60px}
section.screen{padding:26px 0 6px;border-bottom:1px solid var(--line)}
section.screen h2{font-family:var(--sans);font-variation-settings:'wdth' 80;font-weight:800;font-size:22px;margin:0 0 10px;text-transform:lowercase}
.tablewrap{overflow-x:auto;-webkit-overflow-scrolling:touch}
table{border-collapse:collapse;width:100%;min-width:860px;font-size:14px}
thead th{position:sticky;top:0;text-align:left;font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--text-3);background:var(--bg);padding:8px 10px;border-bottom:1px solid var(--line-2)}
tbody th,tbody td{padding:9px 10px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left;font-weight:400}
tbody th{width:22%}
tbody th code{font-family:var(--mono);font-size:12px;color:var(--text-2);word-break:break-all}
td.def{width:24%;color:var(--text-2)}
td.lime{width:24%;background:var(--lime-dim);color:var(--text);font-weight:600}
td.board{width:14%;color:var(--board);font-family:var(--mono);font-size:12.5px;background:var(--board-dim)}
td.board.same{color:var(--text-3);background:transparent;font-style:italic}
td.mark{width:16%;background:var(--mark-dim)}
td.mark input{width:100%;min-height:36px;padding:6px 8px;border:1px solid var(--line-2);border-radius:3px;background:var(--bg-2);color:var(--text);font:inherit;font-size:13px}
td.mark input:focus-visible{outline:2px solid var(--mark);outline-offset:1px}
td.mark input.set{border-color:var(--mark)}
tr[hidden]{display:none}
.export{padding:24px 20px 40px;border-top:1px solid var(--line)}
.export h2{font-size:18px;margin:0 0 8px;text-transform:lowercase;font-variation-settings:'wdth' 80;font-weight:800}
.export p{color:var(--text-2);max-width:62ch;margin:0 0 10px}
.export textarea{width:100%;min-height:180px;padding:10px 12px;border:1px solid var(--line-2);border-radius:4px;background:var(--bg-2);color:var(--text);font-family:var(--mono);font-size:12.5px;line-height:1.5}
.status{font-family:var(--mono);font-size:12px;color:var(--lime);min-height:1.4em;margin-top:6px}
@media (max-width:640px){
  header{padding:22px 14px 10px} .tools,nav.jump{padding-left:14px;padding-right:14px} main{padding:0 14px 40px}
  table{min-width:760px;font-size:13.5px}
}
@media (prefers-reduced-motion: reduce){*{scroll-behavior:auto!important}}
</style>
<header>
  <div class="eyebrow">P9 prose pass · your marks</div>
  <h1>limelight, beside the <span class="m">clinical</span> default</h1>
  <p class="lede"><b>${total} rows</b>, one per key a skin overrides, generated from the committed tables and never retyped. The register is your call, not the model's. Read it on your phone if you can; that is where the strings land.</p>
  <p class="lede">Type in the last column. Marks persist in this browser. When you are done, copy the block at the bottom and paste it back to me.</p>
  <div class="marks"><span><b>keep</b> ships the string</span><span><b>cut</b> drops the row, clinical stands</span><span><b>anything else</b> is the string you want, verbatim</span><span>blank = keep</span></div>
  <div class="rules">
    <p><b>Two things a mark cannot change.</b> A skin changes words, never facts: every <code>{slot}</code>, unit, and defined quantity name survives every rewrite.</p>
    <p>A skin never jokes on a control whose misreading costs data. The wipe, import, legacy delete, export, save failures, reminder states, and install steps have no rows and will not get any; the refusals are listed by key in <code>src/content/copy.limelight.ts</code>.</p>
    <p>Frozen at your request: <code>advice.drinkToThirst</code> = hydrate or diedrate, <code>status.prStamp</code> = MOTHER, <code>button.startSession</code> = LET'S GO BABES. Mark them like any row if you change your mind.</p>
  </div>
</header>
<div class="tools">
  <input type="search" id="q" placeholder="Filter rows by key or text" aria-label="Filter rows">
  <span class="count" id="count">${total} of ${total}</span>
  <button type="button" class="quiet" id="clear">Clear marks</button>
  <button type="button" id="assemble">Assemble marks</button>
</div>
<nav class="jump" aria-label="Screens">${nav}</nav>
<main>
${tables}
</main>
<section class="export" id="export">
  <h2>your marks, ready to paste</h2>
  <p>One line per marked row, in the form the P9 pass reads. Rows you left blank are not listed; they ship as written.</p>
  <textarea id="out" readonly aria-label="Assembled marks" placeholder="Press Assemble marks."></textarea>
  <div class="status" id="status" role="status" aria-live="polite"></div>
</section>
<script>
(function(){
  var KEY='fti-limelight-marks-v1';
  var inputs=Array.prototype.slice.call(document.querySelectorAll('td.mark input'));
  var store={};
  try{store=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch(e){store={};}
  inputs.forEach(function(el){
    var k=el.getAttribute('data-key');
    if(store[k]){el.value=store[k];el.classList.add('set');}
    el.addEventListener('input',function(){
      var v=el.value.trim();
      if(v){store[k]=el.value;el.classList.add('set');}else{delete store[k];el.classList.remove('set');}
      try{localStorage.setItem(KEY,JSON.stringify(store));}catch(e){}
    });
  });
  var rows=Array.prototype.slice.call(document.querySelectorAll('tbody tr'));
  var q=document.getElementById('q'),count=document.getElementById('count');
  q.addEventListener('input',function(){
    var t=q.value.trim().toLowerCase(),shown=0;
    rows.forEach(function(r){var hit=!t||r.getAttribute('data-search').indexOf(t)!==-1;r.hidden=!hit;if(hit)shown++;});
    count.textContent=shown+' of '+rows.length;
  });
  var out=document.getElementById('out'),status=document.getElementById('status');
  document.getElementById('assemble').addEventListener('click',function(){
    var lines=[];
    rows.forEach(function(r){var k=r.getAttribute('data-key');var v=(store[k]||'').trim();if(v){lines.push('- \`'+k+'\`: '+v);}});
    out.value=lines.length?lines.join('\\n'):'(no marks yet)';
    status.textContent=lines.length+' marked row'+(lines.length===1?'':'s')+'. Select the text and copy it.';
    out.focus();out.select();
    if(navigator.clipboard&&lines.length){navigator.clipboard.writeText(out.value).then(function(){status.textContent=lines.length+' marked rows copied to the clipboard.';},function(){});}
  });
  document.getElementById('clear').addEventListener('click',function(){
    if(!confirm('Clear every mark on this page?'))return;
    store={};try{localStorage.removeItem(KEY);}catch(e){}
    inputs.forEach(function(el){el.value='';el.classList.remove('set');});
    out.value='';status.textContent='Marks cleared.';
  });
})();
</script>
`;
writeFileSync(OUT, html);
console.log('sections', sections.length, 'rows', total, 'bytes', Buffer.byteLength(html));
